BOOL __fastcall MonsterNeedsToOpenDoor(::SGAMEDATA * pGame, D2UnitStrc * pUnit, D2AiParamStrc * pAiParam) {
    D2MonsterAiParameterStruct params;
    /* Open Door */ if (!(*((uint8_t*)pAiParam->pMonStats + 0xc) & (uint8_t)gadwBitMasks[3])) {
      return 0;
    }

    eCollisionFlags eCollision = D2Common::PATH::DynamicPath::CheckAndGetCollisionFlag(pUnit->pPath.pDynamicPath);
    if ((eCollision & COLLIDE_DOOR) == COLLIDE_NONE) {
      return 0;
    }

    params.pBestUnit = 0;
    params.nBestDistance = 9;
    ForEach(pGame, pUnit, &params, nullptr, 8);
    if (!params.pBestUnit) {
      return 0;
    }

    D2ObjectsTxt* pObjectsTxt = D2Common::DATATBLS::ObjectTbls::TXT_Objects_GetLine(params.pBestUnit->nClassId);
    if (pObjectsTxt->MonsterOK) {
      D2UnitStrc* pDoor = params.pBestUnit;
      Objects::ObjectsMode::Interact(pGame, pUnit, 2, pDoor->nUnitGUID);
      PlanNextAiMove(pGame, pUnit, 5);
      return 1;
    }

    return 0;
}

// AI tick for summoned monsters: verifies the owning unit is still alive and reachable. If owner is dead or not found, clears nOwnerGUID and returns 0. If alive and close (dist &lt; 2 and owner is player), walks toward owner; if distant (&gt;= 0x15) applies combat stat 7 and walks randomly around owner. Returns 1 when the summon moved, 0 otherwise.
BOOL __fastcall SUMMON_CheckOwnerAlive(::SGAMEDATA * pGame, D2UnitStrc * pUnit, D2AiParamStrc * pAiParam) {
    BOOL bOwnerDead;
    int32_t nMonsterId;
    D2AiGeneralStrc* pAi = pAiParam->pMonsterAiGeneral;
    if (pAi->nOwnerGUID == -1) {
      return 0;
    }
    if (!pUnit) {
      nMonsterId = -1;
    } else {
      nMonsterId = pUnit->nClassId;
    }

    uint32_t bHasOwnerFlag = D2Client::Source::ClientEngine::GetSomeMonsterStatFlag(nMonsterId, 2);
    if (!bHasOwnerFlag) {
      pAi->nOwnerGUID = -1;
      return 0;
    }

    D2UnitStrc* pOwner;
    pOwner = UNIT::SUnit::FindUnitFromTable(pGame, pAi->eOwnerType, pAi->nOwnerGUID);
    if (!pOwner) {
      pAi->nOwnerGUID = -1;
      return 0;
    }

    bOwnerDead = UNIT::SUnit::CheckForModeZeroDeath(pOwner);
    if (bOwnerDead) {
      pAi->nOwnerGUID = -1;
      return 0;
    }

    nMonsterId = AI::GetDistance(pUnit, pOwner);
    if (nMonsterId <= 1 && pAi->eOwnerType == UNIT_PLAYER) {
      nMonsterId = WalkTowardsUnitOffset(pGame, pUnit, pOwner, '\x13', 1);
      if (nMonsterId) {
        return 1;
      }
    } else {
      if (nMonsterId <= 0x14) {
        return 0;
      }

      ApplyCombatAndMonStats(pUnit, 7, 0, '(');
    }

    WalkRandomOffsetAroundUnit(pGame, pUnit, pOwner, 0x13);
    return 1;
}

// AI STAGE 1 - EARLY BAILOUT:
// 1. Stunned check (returns 3-frame delay)
// 2. Door opening check (opens door, returns)
// 3. Summon owner alive check (kills summon if owner dead)
// Returns 1 to skip remaining AI stages
BOOL __fastcall CheckStunnedOpenDoorAndParent(::SGAMEDATA * pGame, D2UnitStrc * pUnit, D2AiParamStrc * pAiParam) {
    BOOL _bOpenedDoor;
    bool bOpenedDoor;
    bool bOwnerAlive;
    eD2States eStunState = D2Common::DATATBLS::ItemStats::UNIT_GetUnitState(pUnit, STATE_stunned);
    if (eStunState != STATE_none) {
      PlanNextAiMove(pGame, pUnit, 3);
      return 1;
    }

    _bOpenedDoor = MonsterNeedsToOpenDoor(pGame, pUnit, pAiParam);
    if (_bOpenedDoor) {
      return 1;
    }

    _bOpenedDoor = SUMMON_CheckOwnerAlive(pGame, pUnit, pAiParam);
    return (uint32_t)(_bOpenedDoor != 0);
}

