    if (nClassId == 0x2c0) {
      (*pCountBuf)++;
      return 0;
    }
    if (nClassId == 0x2c1) {
      pCountBuf[1]++;
      return 0;
    }
    if (nClassId == 0x2c5) {
      pCountBuf[2]++;
      return 0;
    }
    if (nClassId == 0x2c7) {
      pCountBuf[5]++;
      return 0;
    }
    if (nClassId == 0x2c8) {
      pCountBuf[7]++;
      return 0;
    }
    if (nClassId != 0x2dc && nClassId != 0x2db && nClassId != 0x2dd) {
      pCountBuf[4]++;
      return 0;
    }

    pCountBuf[6]++;
    return 0;
