int32_t __fastcall WalkRandomOffset(::SGAMEDATA * pGame, D2UnitStrc * pUnit, uint32_t nRadius) {
    int nX;
    int nY;
    uint32_t nWalkOffsetY;
    eD2UnitType eUnitType = pUnit->eUnitType;
    if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
      nX = pUnit->pPath.pStaticPath->nPosX;
    } else if (pUnit->pPath.pDynamicPath) {
      nX = D2Common::PATH::DynamicPath::GetXPos(pUnit->pPath.pDynamicPath);
    } else {
      nX = 0;
    }

    eUnitType = pUnit->eUnitType;
    if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
      nY = pUnit->pPath.pStaticPath->nPosY;
    } else if (pUnit->pPath.pDynamicPath) {
      nY = D2Common::PATH::DynamicPath::GetYPos(pUnit->pPath.pDynamicPath);
    } else {
      nY = 0;
    }

    D2SeedStrc* pSeed = &pUnit->sSeed;
    D2SeedStrc sSeedNext = D2_SEED_NEXT(pUnit->sSeed);
    pSeed->nSeedHigh = sSeedNext.nSeedHigh;
    pSeed->nSeedLow = sSeedNext.nSeedLow;
    if (sSeedNext.nSeedLow & 1) {
      nRadius &= 0xff;
      nWalkOffsetY = D2Client::Archive::RANDOM_RandomNumberSelector(pSeed, nRadius);
    } else {
      nWalkOffsetY = nRadius & 0xff;
      nRadius = D2Client::Archive::RANDOM_RandomNumberSelector(pSeed, nWalkOffsetY);
    }

    sSeedNext = D2_SEED_NEXT(*pSeed);
    pSeed->nSeedHigh = sSeedNext.nSeedHigh;
    pSeed->nSeedLow = sSeedNext.nSeedLow;
    if (sSeedNext.nSeedLow & 1) {
      nRadius = -nRadius;
    }

    sSeedNext = D2_SEED_NEXT_VAL(sSeedNext);
    *pSeed = sSeedNext;
    if (sSeedNext.nSeedLow & 1) {
      nWalkOffsetY = -nWalkOffsetY;
    }

    int32_t iVar1 = StartMonsterMove(pGame, pUnit, nullptr, Walk, nRadius + nX, nWalkOffsetY + nY, '\x01', '\0');
    return iVar1;
}

// Sends an NPC dialogue message to a player, either as a 0x27 NPC-info network packet (bSendPacket != 0) or as a hover-text overlay on the NPC unit (bSendPacket == 0). In packet mode, builds a minimal D2GSPacketSrv0x27 with one message entry and sends it to the player's client. In hover mode, formats the message index into a string, allocates a D2HoverTextStrc on the NPC, links it to the room update list, sets UNITFLAG_HASTXTMSG, and schedules an expiry event (event type 6). No-ops if nMessageId is 0.
// @sourcefile .\Ai\AiTatics.cpp
void __fastcall SendNpcMessageOrHoverText(::SGAMEDATA * pGame, D2UnitStrc * pNpc, D2UnitStrc * pPlayer, uint32_t nMessageId, BOOL bSendPacket) {
    D2ClientStrc* pClient;
    D2HoverTextStrc* pHover;
    D2GSPacketSrv0x27 sNpcInfoPacket;
    char szMessageIdStr[12];
    if ((short int)nMessageId) {
      if (bSendPacket) {
        pClient = UNIT::SUnit::SUNIT_GetClient(pPlayer, ".\\Ai\\AiTatics.cpp", 0x2cb);
        sNpcInfoPacket.nId = 0x27;
        if (!pNpc) {
          sNpcInfoPacket.nUnitGUID = -1;
        } else {
          sNpcInfoPacket.nUnitGUID = pNpc->nUnitGUID;
        }

        sNpcInfoPacket.eUnitType = 1;
        sNpcInfoPacket.nMessageCount = 1;
        sNpcInfoPacket.aMessages[0].bShow = '\x03';
        sNpcInfoPacket.aMessages[0].nMessage = (short int)nMessageId;
        GAME::SCmd::NET_D2GS_SERVER_Send_0x27_NpcInfo(pClient, &sNpcInfoPacket);
        return;
      }

      sprintf(szMessageIdStr, "%d", nMessageId & 0xffff);
      if (pNpc && pNpc->pHoverText) {
        D2Common::Chat::Free(pGame->pMemoryPool, pNpc->pHoverText);
      }

      pHover = D2Common::Chat::Alloc(pGame->pMemoryPool, szMessageIdStr, pGame->dwGameFrame);
      if (pHover) {
        if (pNpc) {
          pNpc->pHoverText = pHover;
        }

        D2Common::Unit::ROOM_LinkUnitToUpdateList(pNpc);
        if (pNpc) {
          pNpc->eUnitFlags |= UNITFLAG_HASTXTMSG;
        }

        GAME::Event::SetEvent(pGame, pNpc, 6, D2Common::Chat::GetExpireFrame(pHover), 0, 0);
      }
    }
}

