    D2Common::PATH::DynamicPath::SetStepNum(pUnitSaved->pPath.pDynamicPath, 1);
    local_38.nTargetX = (int)(((D2UnitStrc*)nTarget)->unk0x19 + nDirX * nStepX * nApproachDir - 0x19);
