// AI think function for stationary NPCs (used by Meshif classId 0xFB and Izual classId 0x196). If no nearby player is found, handles quest-specific completion triggers: for Meshif checks Q14_IsNpcStationary and plays A2Q6 completion sound; for Izual checks Q26_CheckIzualNearPlayer and plays A4Q2 completion sound. If a player is near but busy trading or AI sub is active, defers action. Otherwise watches distance threshold and periodically emits an attract-sound event.
void __fastcall AITHINK_Fn1_NpcStationary(::SGAMEDATA * pGame, D2UnitStrc * pUnit, D2AiParamStrc * pAiParam) {
    int32_t nTradeState;
    BOOL bHasAiSub;
    bool bNearestUnitGuid[4];
    D2MonsterAiStrc* pMonsterAi;
    D2AiGeneralStrc* pMonsterAiGeneral;
    bNearestUnitGuid[0] = false;
    bNearestUnitGuid[1] = false;
    bNearestUnitGuid[2] = false;
    bNearestUnitGuid[3] = false;
    D2UnitStrc* pUnit_00 = MONSTERAI_FindNearestUnit(pGame, pUnit, bNearestUnitGuid);
    if (!pUnit_00 || pUnit_00 == pUnit) {
      if (pUnit) {
        if (pUnit->nClassId == 0xfb) {
          bHasAiSub = Quests::QUESTS::A2Q7::Q14_IsNpcStationary(pGame, pUnit);
          if (bHasAiSub) {
            bHasAiSub = AI_Monster_TryDefaultIdleIfNoSub(pGame, pUnit);
            if (bHasAiSub) {
              MONSTERAI_CommandSkillAtPosition(pGame, pUnit, 0, 0, 0);
              Quests::QUESTS::A2Q6::Q14_PlayCompletionSoundAll(pGame);
              return;
            }
          }
        } else if (pUnit->nClassId == 0x196) {
          bHasAiSub = Quests::QUESTS::A4Q2::Q26_CheckIzualNearPlayer(pGame, (int32_t)pUnit);
          if (bHasAiSub) {
            bHasAiSub = AI_Monster_TryDefaultIdleIfNoSub(pGame, pUnit);
            if (bHasAiSub) {
              MONSTERAI_CommandSkillAtPosition(pGame, pUnit, 0, 0, 0);
              Quests::QUESTS::A4Q2::Q26_PlayIzualCompleteSoundToAll(pGame);
              return;
            }
          }
        }
      }
    } else {
      int32_t nDistToPlayer;
      nDistToPlayer = AI::GetDistance(pUnit, pUnit_00);
      if (!pUnit || pUnit->eUnitType != UNIT_MONSTER || !pUnit->pUnitData.pUnitDataMonster) {
        pMonsterAi = 0;
      } else {
        pMonsterAi = pUnit->pUnitData.pUnitDataMonster->pMonsterAi;
      }
      if (pUnit_00->eUnitType == UNIT_PLAYER) {
        nTradeState = PLAYER::Player::GetPlayerTradeTickOrBusy(pUnit_00);
        if (nTradeState == 1) {
          PlanNextAiMove(pGame, pUnit, 10);
          return;
        }
      }

      bHasAiSub = MonsterAI::HasAiSub(pMonsterAi);
      if (bHasAiSub) {
        PlanNextAiMove(pGame, pUnit, 10);
        return;
      }

      pMonsterAiGeneral = pAiParam->pMonsterAiGeneral;
      if (nDistToPlayer >= 0x18) {
        if (pMonsterAiGeneral->dwArg1 <= 0) {
          pMonsterAiGeneral->dwArg1 = 0x3c;
        }

        pMonsterAiGeneral->dwArg1--;
        PlanNextAiMove(pGame, pUnit, 0x14);
        return;
      }
      if (pMonsterAiGeneral->dwArg1) {
        pMonsterAiGeneral->dwArg1--;
        PlanNextAiMove(pGame, pUnit, 0x14);
        return;
      }

      pMonsterAiGeneral->dwArg1 = 0x3c;
      if (pUnit_00->eUnitType == UNIT_PLAYER) {
        UNIT::SUnit::SetupUpdateEvent_AttachEventSound(pUnit, 0x12, pUnit_00);
      }
    }

    PlanNextAiMove(pGame, pUnit, 0x14);
}

